  'Anne sütü alan bebekler bazen birkaç gün kaka yapmayabilir; yumuşaksa genellikle normaldir.': 'Bayi ASI kadang tidak BAB beberapa hari; jika fesesnya lembek, biasanya normal.',
  'Anne sütü alan bebeklerin kakası doğal olarak yumuşak ve sıktır; bu ishal değildir.': 'Bayi yang menyusu ASI wajar memiliki feses lembek dan sering; ini bukan diare.',
