  'Annelik ve günlük yaşamın yükü kaygıyı artırabilir; kaygıyı tanımak ve yönetmek mümkündür.': 'Beban menjadi ibu dan kehidupan sehari-hari bisa meningkatkan kecemasan; kecemasan bisa dikenali dan dikelola.',
  'Annenden, kayınvalidenden öğrendiğin tarifleri “Tarif ekle” ile yaz. Tarif detaylarındaki “Aile tarif defterime ekle” ile hazır tarifleri de buraya kaydedebilirsin.': 'Tuliskan resep dari ibu atau ibu mertua Anda dengan "Tambah resep". Anda juga bisa menyimpan resep jadi di sini dengan "Tambahkan ke buku resep keluarga saya" pada detail resep.',
