  'Bal ve cevizi ekleyip karıştırın; bu kırıntıları meyvelerin üzerine eşit serpin.': 'Tambahkan madu dan kenari lalu aduk; taburkan remahan ini merata di atas buah.',
  'Bal ve ilave şeker eklemeyin.': 'Jangan tambahkan madu atau gula tambahan.',
  'Bal, tarçın ve eritilmiş tereyağını karıştırıp üzerine gezdirin; suyu kabın dibine dökün.': 'Campur madu, kayu manis, dan mentega leleh lalu siram di atasnya; tuang air ke dasar pinggan.',
