  'Balkabağını ve mercimeği ekleyip 2 dakika karıştırın.': 'Masukkan labu dan lentil lalu aduk 2 menit.',
  'Balkabağının tatlılığı limonla dengelenir; servis sırasında mutlaka limon sıkın.': 'Rasa manis labu diimbangi lemon; selalu peras lemon saat menyajikan.',
