  'Balık': 'Ikan',
  'Balık eti opaklaşıp kolay ayrılana kadar 18-22 dakika pişirin.': 'Panggang 18-22 menit hingga ikan tidak bening dan mudah terlepas.',
  'Balık eti tamamen pişip kolay ayrılana kadar 25-30 dakika fırınlayın.': 'Panggang 25-30 menit hingga ikan matang dan mudah terlepas.',
  'Balık kokulu gri akıntı bakteriyel vajinozu düşündürebilir.': 'Keputihan keabu-abuan berbau amis bisa menandakan vaginosis bakteri.',
  'Balık köftesi': 'Perkedel ikan',
  'Balık opaklaşıp kolay ayrılana kadar yaklaşık 15-20 dakika pişirin.': 'Panggang sekitar 15-20 menit hingga ikan tidak bening dan mudah terlepas.',
  'Balık parçalarını tuz ve karabiberle tatlandırıp sebzelerin arasına yerleştirin, kalan sosu üzerine gezdirin.': 'Bumbui potongan ikan dengan garam dan merica, letakkan di antara sayuran, dan siram sisa saus.',
  'Balık tamamen pişene kadar 18-22 dakika fırınlayıp maydanozla servis edin.': 'Panggang 18-22 menit hingga ikan matang dan sajikan dengan peterseli.',
  'Balık tamamen pişene kadar 20-25 dakika fırınlayıp maydanozla servis edin.': 'Panggang 20-25 menit hingga ikan matang dan sajikan dengan peterseli.',
  'Balık tamamen pişene ve eti kolay ayrılana dek yaklaşık 18–22 dakika pişirin.': 'Panggang sekitar 18–22 menit hingga ikan matang dan mudah terurai.',
  'Balık tamamen pişip kolay ayrılana kadar yaklaşık 18–22 dakika fırınlayın.': 'Panggang sekitar 18–22 menit hingga ikan matang dan mudah terurai.',
  'Balık ve deniz ürünleri': 'Ikan dan makanan laut',
  'Balık, eti çatalla kolayca ayrılıyorsa pişmiştir; fazla pişirmek kurutur.': 'Ikan matang bila dagingnya mudah terlepas dengan garpu; terlalu lama dimasak membuatnya kering.',
  'Balıkları sebzelerin üzerine dizin, kalan tuzu ve limon suyunu ekleyin.': 'Tata ikan di atas sayuran lalu tambahkan sisa garam dan air lemon.',
  'Balıkları temizleyip kağıt havluyla kurulayın.': 'Bersihkan ikan dan keringkan dengan tisu dapur.',
  'Balıkları temizleyip kurulayın.': 'Bersihkan dan keringkan ikan.',
  'Balıkları temizleyip kılçık kontrolü yapın.': 'Bersihkan ikan dan periksa durinya.',
  'Balıkları yağlayıp içlerine maydanoz koyun.': 'Olesi ikan dengan minyak dan isi dengan peterseli.',
  'Balıkları üzerine yerleştirin, içine limon dilimleri koyun.': 'Letakkan ikan di atasnya dan isi bagian dalamnya dengan irisan lemon.',
  'Balıkları üzerine yerleştirip limon ve yağ ekleyin.': 'Letakkan ikan di atasnya dan tambahkan lemon serta minyak.',
  'Balıkların iki yüzüne çapraz çizikler atın; tuz, karabiber ve kekik sürün.': 'Sayat kedua sisi ikan secara diagonal; lumuri garam, lada hitam, dan thyme.',
  'Balıkların karnına sarımsak dilimleri, maydanoz sapları ve 2 dilim limon yerleştirin.': 'Masukkan irisan bawang putih, batang peterseli, dan 2 iris lemon ke perut ikan.',
  'Balıkların üzerine kalan zeytinyağını gezdirin, 2\'şer dilim limon yerleştirin.': 'Siram sisa minyak zaitun ke ikan dan letakkan 2 iris lemon di atas masing-masing.',
  'Balıklı sebze güveç': 'Kaserol ikan dan sayuran',
  'Balıksız sebzeli bulgur': 'Bulgur dengan sayur (tanpa ikan)',
  'Balığı sebzelerle birlikte başta koyarsanız fazla pişip dağılır; son 15 dakikada ekleyin.': 'Jika ikan dimasukkan sejak awal bersama sayuran, ikan akan terlalu matang dan hancur; masukkan pada 15 menit terakhir.',
  'Balığı tepsiye yerleştirin; etrafına limon ve domates dilimleri dizin.': 'Letakkan ikan di loyang dan tata irisan lemon dan tomat di sekelilingnya.',
  'Balığı çevirirken iki spatula kullanmak dağılmasını önler.': 'Gunakan dua spatula saat membalik agar ikan tidak hancur.',
  'Balığın gözü beyazlaşıp dışarı çıkıyorsa pişmiştir.': 'Ikan matang jika matanya memutih dan menonjol.',
  'Balığın içini ve dışını tuz, karabiber ve 2 yemek kaşığı zeytinyağı ile ovun; karnına 2 dilim limon ve kekik dallarını yerleştirin.': 'Lumuri ikan bagian dalam dan luar dengan garam, merica, dan 2 sdm minyak zaitun; masukkan 2 iris lemon dan tangkai thyme ke perutnya.',
  'Bamya yemeği': 'Tumis okra',
  'Bamyaları ekleyin; şeker ve sıcak suyu ilave edin, bamyalar dağılmasın diye karıştırmadan tencereyi sallayın.': 'Masukkan okra, gula, dan air panas; goyangkan panci alih-alih mengaduk agar okra tetap utuh.',
  'Bamyaları geniş bir kapta limon suyu ve tuzla harmanlayıp 15 dakika bekletin, ardından yıkayıp süzün.': 'Aduk okra dengan air lemon dan garam di wadah lebar, diamkan 15 menit, lalu cuci dan tiriskan.',
  'Bamyaları yıkayıp saplarını koni biçiminde ayıklayın.': 'Cuci okra dan rapikan tangkainya berbentuk kerucut.',
  'Bamyaları, limon suyunu ve suyu ilave edin.': 'Masukkan okra, air lemon, dan air.',
  'Bamyaların başını kozalak gibi yontup limonlu suda bekletin.': 'Raut pangkal okra berbentuk kerucut lalu rendam dalam air lemon.',
  'Bamyaların şapkalarını konik şekilde, iç kısmı açılmadan kalemtıraş gibi açın.': 'Raut ujung okra berbentuk kerucut seperti rautan pensil tanpa membuka bagian dalamnya.',
  'Bamyalı limonlu dana güveç': 'Semur sapi okra lemon',
  'Bamyayı kaşıkla karıştırmayın; tencereyi sallayın.': 'Jangan aduk okra dengan sendok; goyangkan panci.',
  'Banyo': 'Mandi',
  'Banyo için destekleyici ekipman.': 'Perlengkapan penunjang saat mandi.',
  'Banyo sonrası nefes alma güçlüğü veya morarma.': 'Sulit bernapas atau kebiruan setelah mandi.',
  'Banyo suyu 36–37 °C civarında olmalıdır; dirsekle kontrol et.': 'Air mandi sebaiknya sekitar 36–37 °C; cek dengan siku.',
  'Banyo süngeri': 'Spons mandi',
  'Banyo termometresi': 'Termometer mandi',
  'Banyo ve bakım kaydı': 'Catatan mandi dan perawatan',
  'Banyo, beslenme, ninni gibi her akşam aynı sırayla yapılan kısa bir rutin oluştur.': 'Buat rutinitas singkat dengan urutan yang sama setiap malam, misalnya mandi, menyusu, dan lagu nina bobo.',
  'Banyo, cilt bakımı ve bez değişimi gibi rutinleri çocuğun ihtiyacına göre düzenleyin.': 'Sesuaikan rutinitas seperti mandi, perawatan kulit, dan ganti popok dengan kebutuhan anak.',
  'Banyodan sonra kıvrım yerlerini iyice kurula.': 'Keringkan lipatan kulit dengan baik setelah mandi.',
  'Banyoyu akşam rutininin parçası yapmak uykuyu kolaylaştırabilir.': 'Menjadikan mandi bagian dari rutinitas malam bisa membantu tidur.',
  'Barbunya pilaki': 'Pilaki kacang borlotti',
  'Barbunya, pazı yaprakları, tuz ve sıcak suyu ilave edin.': 'Tambahkan kacang, daun sawi chard, garam, dan air panas.',
  'Barbunyalı pazı yemeği': 'Sawi chard dengan kacang borlotti',
  'Barbunyayı ezip rendelenmiş soğan, yumurta ve galeta unuyla yoğurun.': 'Hancurkan kacang dan uleni dengan bawang parut, telur, dan tepung roti.',
  'Bardaklara paylaştırın.': 'Bagi ke gelas-gelas.',
