  'Bazı ağrı kesiciler gebeliğin belirli dönemlerinde önerilmez.': 'Beberapa obat pereda nyeri tidak dianjurkan di tahap kehamilan tertentu.',
  'Bazı belirtiler beklemeden sağlık kuruluşuna başvurmayı gerektirir.': 'Beberapa gejala mengharuskan Anda segera ke fasilitas kesehatan tanpa menunggu.',
