  'Bebek arabası': 'Kereta dorong bayi',
  'Bebek ağlıyor, başını çeviriyor veya geriliyorsa ara vermek gerekir.': 'Jika bayi menangis, memalingkan kepala, atau kaku, beri jeda.',
  'Bebek bakımı': 'Perawatan bayi',
  'Bebek bakımı sırasında uyku bölünmesi kaçınılmazdır; ama uzun süreli uykusuzluk ruh sağlığını etkiler.': 'Tidur terputus tak terhindarkan saat merawat bayi, tetapi kurang tidur jangka panjang memengaruhi kesehatan jiwa.',
  'Bebek bakımı, büyüme, adet ve gebelik kayıtları cihazın güvenli deposunda şifrelenir.': 'Catatan perawatan, pertumbuhan, haid, dan kehamilan dienkripsi di penyimpanan aman perangkat.',
  'Bebek bakımı, gebelik, yemek planlama veya uygulamanın kullanımı hakkında genel bir soru sorabilirsiniz.': 'Anda dapat bertanya hal umum tentang perawatan bayi, kehamilan, perencanaan makan, atau penggunaan aplikasi.',
  'Bebek banyosu': 'Memandikan bayi',
  'Bebek başını sürekli aynı tarafa çeviriyor ve diğer tarafa dönemiyorsa.': 'Jika bayi selalu menoleh ke sisi yang sama dan tidak bisa menoleh ke sisi lain.',
  'Bebek beslenme rehberi': 'Panduan makan bayi',
  'Bebek beslenmesi': 'Gizi bayi',
  'Bebek bezi': 'Popok',
  'Bebek birkaç santimetre suda bile boğulabilir.': 'Bayi bisa tenggelam di air yang hanya beberapa sentimeter.',
  'Bebek bütçesi': 'Anggaran bayi',
  'Bebek bütçesini ve ihtiyaç listesini uygulamadaki alışveriş bölümünde hazırla.': 'Siapkan anggaran bayi dan daftar kebutuhan di bagian belanja aplikasi.',
  'Bebek cildi ve döküntüler': 'Kulit bayi dan ruam',
  'Bebek dik otururken ve gözetim altında besle.': 'Beri makan bayi dalam posisi duduk tegak dan diawasi.',
  'Bebek ekle': 'Tambah bayi',
  'Bebek forumu bağlantısı ve erişim politikaları': 'Koneksi dan kebijakan akses forum bayi',
  'Bebek gelince çift ilişkisi de değişir; açık iletişim ve adil iş bölümü yükü hafifletir.': 'Kehadiran bayi juga mengubah hubungan pasangan; komunikasi terbuka dan pembagian tugas yang adil meringankan beban.',
  'Bebek gelişimi ve kayıtları': 'Perkembangan dan catatan bayi',
  'Bebek hareketleri': 'Gerakan bayi',
  'Bebek hareketlerinde azalma.': 'Gerakan bayi berkurang.',
  'Bebek hareketlerinde belirgin azalma (son aylarda).': 'Gerakan bayi jelas berkurang (di bulan-bulan terakhir).',
  'Bebek hareketlerinde belirgin azalma veya durma: hemen başvur.': 'Gerakan bayi jelas berkurang atau berhenti: segera periksakan.',
  'Bebek hareketlerinde belirgin azalma, kanama, su gelmesi, düzenli kasılmalar, şiddetli baş ağrısı veya görme bozukluğu: aynı gün başvur. Acil durumda 112.': 'Gerakan bayi jelas berkurang, perdarahan, keluar cairan, kontraksi teratur, sakit kepala hebat, atau gangguan penglihatan: periksakan hari itu juga. Dalam keadaan darurat, hubungi nomor darurat setempat.',
  'Bebek hareketlerini say (10 hareket)': 'Hitung gerakan bayi (10 gerakan)',
  'Bebek havlusu': 'Handuk bayi',
  'Bebek her uykuda sırtüstü yatırılmalıdır; yan veya yüzüstü yatış önerilmez.': 'Tidurkan bayi telentang setiap kali tidur; posisi miring atau tengkurap tidak dianjurkan.',
  'Bebek hızla büyüdüğü için kıyafet ve ekipmanlar kısa süre kullanılır.': 'Bayi tumbuh cepat, sehingga pakaian dan perlengkapan hanya dipakai sebentar.',
  'Bebek hızla kilo alır; doğuma hazırlık ve bebek hareketlerinin takibi önem kazanır.': 'Berat bayi bertambah cepat; persiapan persalinan dan memantau gerakan menjadi penting.',
  'Bebek inince nefes rahatlar ama idrar sıklığı artar.': 'Saat bayi turun, bernapas lebih mudah tetapi lebih sering buang air kecil.',
  'Bebek isimleri': 'Nama bayi',
  'Bebek istedikçe, günde en az 8–12 kez emzir.': 'Susui sesuai keinginan bayi, minimal 8–12 kali sehari.',
  'Bebek için: 2–3 takım zıbın ve tulum, şapka, çorap, battaniye, yenidoğan bezi.': 'Untuk bayi: 2–3 set baju dan baju terusan, topi, kaus kaki, selimut, popok bayi baru lahir.',
