  'Bebek uyanıkken ve gözetim altındayken kısa yüzüstü oyun fırsatları sağlayın; zorlanma varsa uzmanla görüşün.': 'Beri kesempatan main tengkurap sebentar saat bayi terjaga dan diawasi; jika ia kesulitan, bicarakan dengan ahli.',
  'Bebek uyku alanında yastık bırakmayın.': 'Jangan tinggalkan bantal di area tidur bayi.',
  'Bebek uyuduktan sonra emzik düşerse yeniden takmak gerekmez.': 'Jika empeng lepas setelah bayi tertidur, tidak perlu dipasang lagi.',
  'Bebek uyurken dinlen; ev işleri için yardım iste.': 'Istirahatlah saat bayi tidur; minta bantuan untuk pekerjaan rumah.',
  'Bebek uyurken her işi yapmaya çalışma; dinlen.': 'Jangan mencoba mengerjakan semuanya saat bayi tidur; istirahatlah.',
  'Bebek ve kadın ekranlarından modül merkezine geçiş denendi': 'Peralihan dari layar bayi dan perempuan ke pusat modul telah diuji',
  'Bebek ve kadın sağlığı araçları bir arada': 'Alat kesehatan bayi dan perempuan dalam satu tempat',
  'Bebek ve çocuk': 'Bayi dan anak',
  'Bebek ve çocuklar sıcağa ve güneşe karşı daha duyarlıdır.': 'Bayi dan anak lebih sensitif terhadap panas dan sinar matahari.',
  'Bebek yatağı': 'Boks bayi',
  'Bebek yeterli ıslak bez yapmıyor veya kilo almıyorsa.': 'Jika popok basah bayi kurang atau berat badan tidak naik.',
