  'Belirtiler genellikle adet başlayınca azalır.': 'Gejala biasanya mereda saat haid dimulai.',
  'Belirtiler için tedavi seçeneklerini hekiminle konuş.': 'Diskusikan pilihan pengobatan keluhan dengan dokter.',
  'Belirtiler iş ve ilişkileri ciddi biçimde etkiliyorsa.': 'Jika gejala sangat mengganggu pekerjaan dan hubungan.',
  'Belirtiler: düzenli kasılmalar, bel ağrısı, kasıkta baskı, akıntıda değişiklik, su gelmesi.': 'Tanda: kontraksi teratur, nyeri pinggang bawah, tekanan di panggul, perubahan keputihan, keluar cairan.',
  'Belirtileri 2–3 döngü boyunca günlüğe kaydet.': 'Catat gejala di jurnal selama 2–3 siklus.',
  'Belirtilmedi': 'Tidak ditentukan',
  'Belirtinin başlangıcını, süresini, eşlik eden bulguları ve ölçüm yöntemini not edin.': 'Catat kapan gejala mulai, berapa lama, tanda lain, dan cara mengukurnya.',
  'Belirtiyi, başladığı saati ve süresini not et.': 'Catat gejala, kapan mulai, dan berapa lama.',
  'Belirtiyi, başlangıç zamanını, süresini ve günlük etkisini not edin. Randevu öncesinde sorularınızı bir araya getirin.': 'Catat gejala, kapan mulai, berapa lama, dan dampaknya pada keseharian. Kumpulkan pertanyaan sebelum janji temu.',
