  'Besin alerjisi bağışıklık sisteminin bir besine aşırı tepkisidir; hafiften hayati tehlikeye kadar değişebilir.': 'Alergi makanan adalah reaksi berlebihan sistem imun terhadap makanan; bisa ringan hingga mengancam nyawa.',
  'Besin ve gözlem kaydı': 'Catatan makanan dan pengamatan',
  'Besleme sırasında pozisyon desteği.': 'Penopang posisi saat menyusui.',
  'Beslenirken yutulan hava rahatsızlık verebilir; düzenli gaz çıkarmak bebeği rahatlatır.': 'Udara yang tertelan saat menyusu bisa membuat tidak nyaman; menyendawakan secara rutin membantu bayi.',
  'Beslenme': 'Gizi',
  'Beslenme ekipmanı seçenekleri.': 'Pilihan perlengkapan makan.',
