  'Beslenme çantası için uygun.': 'Cocok untuk bekal.',
  'Beslenme, oyun, uyku ve güvenlik önerileri': 'Tips makan, bermain, tidur, dan keamanan',
  'Beslenme, uyku ve büyüme kaydı eklenebiliyor': 'Catatan makan, tidur, dan pertumbuhan dapat ditambahkan',
  'Beslenme, uyku ve gelişim konularında genel bilgilendirme içerikleri.': 'Informasi umum tentang makan, tidur, dan perkembangan.',
  'Beslenme, uyku ve önemli bakım bilgilerini bakım verenlerle güvenli biçimde paylaşmak için günlük özet oluşturun.': 'Buat ringkasan harian untuk berbagi informasi makan, tidur, dan perawatan penting dengan pengasuh secara aman.',
