  'Beslenmenin ortasında ve sonunda bebeği omzuna dikey alıp sırtını sıvazla.': 'Di tengah dan akhir menyusu, gendong bayi tegak di bahu dan usap punggungnya.',
  'Beslenmeyi yarıya indirme, ıslak bezin azalması.': 'Asupan menyusu turun separuh, popok basah berkurang.',
