  'Beyaz fasulyenin üçte ikisini ve sıcak suyu ekleyin; kaynayınca kısık ateşte kapağı kapalı 15 dakika, kabaklar iyice yumuşayana kadar pişirin.': 'Masukkan dua pertiga kacang dan air panas; setelah mendidih, masak tertutup dengan api kecil 15 menit hingga zukini sangat lunak.',
