  'Doz ve kullanım süresini doktorunun ya da eczacının önerisine göre gir. Uygulama doz önermez. Gebelikte ve emzirirken her yeni ilaç için doktoruna danış.': 'Masukkan dosis dan durasi sesuai anjuran dokter atau apoteker. Aplikasi tidak merekomendasikan dosis. Tanyakan kepada dokter setiap obat baru selama hamil dan menyusui.',
