  'Doğru kavramada bebeğin ağzı geniş açık, dudakları dışa dönük ve meme başının çevresindeki koyu alanın büyük kısmı ağzındadır.': 'Pada pelekatan yang baik, mulut bayi terbuka lebar, bibir terlipat keluar, dan sebagian besar area gelap di sekitar puting masuk ke mulut.',
  'Doğru takılmış ve yaşa uygun oto koltuğu trafik kazalarında ölüm ve ağır yaralanma riskini büyük ölçüde azaltır.': 'Kursi mobil yang sesuai usia dan terpasang benar sangat menurunkan risiko kematian dan cedera berat dalam kecelakaan.',
  'Doğru temizlik, ayırma, pişirme ve soğutma gıda kaynaklı hastalıkları önler.': 'Membersihkan, memisahkan, memasak, dan mendinginkan dengan benar mencegah penyakit akibat makanan.',
