  'Emzirme Yastığı': 'Bantal Menyusui',
  'Emzirme döneminde enerji ve sıvı ihtiyacı artar; özel bir diyet çoğu zaman gerekmez.': 'Kebutuhan energi dan cairan meningkat saat menyusui; diet khusus biasanya tidak diperlukan.',
  'Emzirme günde yaklaşık 450–500 kcal ek enerji gerektirir.': 'Menyusui membutuhkan sekitar 450–500 kkal tambahan per hari.',
  'Emzirme hakkında bilgi edin; uygulamadaki rehberden başlayabilirsin.': 'Pelajari tentang menyusui; Anda bisa mulai dari panduan di aplikasi.',
  'Emzirme oturana kadar (genellikle 3–4 hafta) emzik vermemek önerilir.': 'Dianjurkan tidak memberi empeng sebelum menyusui lancar (biasanya 3–4 minggu).',
  'Emzirme sonrası birkaç damla sütü meme ucuna sürüp kurumaya bırak.': 'Setelah menyusui, oleskan beberapa tetes ASI di puting dan biarkan kering.',
