  'Folyoyu açıp 10 dakika daha kızartın, 15 dakika dinlendirin.': 'Buka aluminium foil, panggang 10 menit lagi hingga kecokelatan, lalu diamkan 15 menit.',
  'Folyoyu açıp 15 dakika kızartın.': 'Buka aluminium foil dan panggang 15 menit hingga kecokelatan.',
  'Folyoyu açıp 220 °C\'de 15 dakika kızartın.': 'Buka aluminium foil dan panggang pada 220 °C selama 15 menit hingga kecokelatan.',
  'Folyoyu kaldırıp 15 dakika daha, köfteler kızarana kadar pişirin.': 'Buka aluminium foil dan panggang 15 menit lagi hingga köfte kecokelatan.',
  'Folyoyu kaldırıp 15 dakika daha, üzeri kızarana ve patatesler yumuşayana kadar pişirin.': 'Buka aluminium foil dan panggang 15 menit lagi hingga atasnya kecokelatan dan kentang lunak.',
  'Folyoyu kaldırıp kalan kaşarı serpin, 15 dakika daha üzeri kızarana ve patatesler bıçakla kolayca delinene kadar pişirin; 10 dakika dinlendirip dilimleyin.': 'Buka foil, taburi sisa keju kaşar, panggang 15 menit lagi hingga kecokelatan dan pisau mudah menembus kentang; diamkan 10 menit lalu potong.',
