  'Fırını 190°C’ye ısıtın. Brokoliyi küçük doğrayıp 5 dakika buharda pişirin; süzerek soğutun.': 'Panaskan oven pada 190 °C. Potong kecil brokoli dan kukus 5 menit; tiriskan lalu dinginkan.',
  'Fırını 190°C’ye ısıtın. Havucu rendeleyip tavada 4 dakika soteleyin; soğutun.': 'Panaskan oven pada 190 °C. Parut wortel, tumis di wajan 4 menit, lalu dinginkan.',
  'Fırını 190°C’ye ısıtın. Ispanağı yıkayıp doğrayın; tavada suyunu çektirip soğutun.': 'Panaskan oven pada 190 °C. Cuci dan cincang bayam; uapkan airnya di wajan lalu dinginkan.',
  'Fırını 190°C’ye ısıtın. Kabağı rendeleyip suyunu sıkın; naneyle kısa süre soteleyip soğutun.': 'Panaskan oven pada 190 °C. Parut zukini dan peras airnya; tumis sebentar dengan mint lalu dinginkan.',
  'Fırını 190°C’ye ısıtın. Közlenmiş biberi süzüp ince doğrayın; fazla suyunu alın.': 'Panaskan oven pada 190 °C. Tiriskan paprika panggang, cincang halus, dan buang kelebihan airnya.',
  'Fırını 190°C’ye ısıtın. Mantarları ince doğrayıp tavada suyunu tamamen çektirin; soğutun.': 'Panaskan oven pada 190 °C. Cincang halus jamur dan uapkan airnya sepenuhnya di wajan; dinginkan.',
  'Fırını 190°C’ye ısıtın. Patatesleri haşlayıp ezin; ince kıyılmış dereotuyla karıştırın.': 'Panaskan oven pada 190 °C. Rebus dan haluskan kentang; campur dengan dill cincang halus.',
  'Fırını 190°C’ye ısıtın. Patlıcanı küçük küp doğrayıp yağda yumuşayana kadar soteleyin; soğutun.': 'Panaskan oven pada 190 °C. Potong terung dadu kecil dan tumis dengan minyak hingga lunak; dinginkan.',
  'Fırını 190°C’ye ısıtın. Pazıyı yıkayıp doğrayın; tavada suyunu çektirip soğutun.': 'Panaskan oven pada 190 °C. Cuci dan potong sawi chard; uapkan airnya di wajan lalu dinginkan.',
  'Fırını 190°C’ye ısıtın. Pırasayı ince doğrayıp yağda 6-8 dakika yumuşatın ve soğutun.': 'Panaskan oven pada 190 °C. Iris halus daun bawang perai, layukan dengan minyak 6–8 menit, lalu dinginkan.',
  'Fırını 190°C’ye ısıtın; sebzeleri eş boyda doğrayın.': 'Panaskan oven 190°C; potong sayuran berukuran sama.',
