  'Gebelik diyabeti geçiren kadınlarda ileride tip 2 diyabet riski artar.': 'Perempuan yang pernah diabetes gestasional berisiko lebih tinggi terkena diabetes tipe 2 di kemudian hari.',
  'Gebelik diyabeti taraması (şeker yükleme testi) 24–28. haftalarda yapılır.': 'Skrining diabetes gestasional (tes toleransi glukosa) dilakukan di minggu 24–28.',
