  'Gebelik günlüğüm 🤰': 'Jurnal kehamilan saya 🤰',
  'Gebelik haftaları son adetin ilk gününden sayılır; bu hafta aslında adet dönemidir ve henüz gebelik yoktur.': 'Minggu kehamilan dihitung dari hari pertama haid terakhir; minggu ini sebenarnya Anda sedang haid dan belum hamil.',
  'Gebelik heyecanla birlikte endişe de getirebilir; duygu dalgalanmaları olağandır.': 'Kehamilan bisa membawa kekhawatiran selain kegembiraan; perubahan suasana hati itu normal.',
