  'Gebelik planlıyorsan erken değerlendirme.': 'Jika merencanakan kehamilan, periksakan diri lebih awal.',
  'Gebelik planlıyorsan folik asit desteğine başla; alkol ve sigarayı bırak.': 'Jika merencanakan kehamilan, mulai asam folat; hentikan alkohol dan rokok.',
