  'Gebelik ve emzirme döneminde içerik konusunda hekiminize danışın.': 'Saat hamil dan menyusui, tanyakan dokter tentang kandungan produk.',
  'Gebelik ve emzirme döneminde özel beslenme gereksinimlerini uzmanla görüşün.': 'Diskusikan kebutuhan gizi khusus saat hamil dan menyusui dengan ahli.',
