  'Gebelik ve kontroller': 'Kehamilan dan pemeriksaan',
  'Gebelik öncesi kontrol için kadın doğum uzmanına veya aile hekimine başvur.': 'Lakukan pemeriksaan pra-kehamilan ke dokter kandungan atau dokter keluarga.',
  'Gebelik, doğum sonrası dönem veya kronik hastalıkta kişisel öneri alın.': 'Minta saran pribadi saat hamil, setelah melahirkan, atau jika punya penyakit kronis.',
  'Gebelik, emzirme ve bebeklik döneminde vegan beslenme uzman eşliğinde planlanmalıdır.': 'Pola makan vegan saat hamil, menyusui, dan masa bayi sebaiknya direncanakan bersama ahli.',
  'Gebelik: 1–40 hafta': 'Kehamilan: minggu 1–40',
  'Gebelikte "iki kişilik" değil, iki kişi için kaliteli beslenmek önemlidir.': 'Saat hamil bukan soal makan "untuk dua orang", melainkan makan dengan baik untuk dua orang.',
  'Gebelikte ateşli ishal (listeria olabilir).': 'Diare disertai demam saat hamil (bisa listeria).',
  'Gebelikte beslenme': 'Gizi saat hamil',
  'Gebelikte birçok ilaç güvenle kullanılabilir; ancak her ilaç ve bitkisel ürün hekime sorulmalıdır.': 'Banyak obat aman dipakai saat hamil, tetapi setiap obat dan produk herbal harus dikonsultasikan ke dokter.',
  'Gebelikte depresyon da görülebilir ve tedavi edilebilir.': 'Depresi juga bisa terjadi saat hamil dan bisa diobati.',
  'Gebelikte egzersiz': 'Olahraga saat hamil',
  'Gebelikte idrar yolu belirtileri.': 'Keluhan saluran kemih saat hamil.',
  'Gebelikte idrar yolu enfeksiyonu tedavi edilmelidir; böbreğe yayılabilir.': 'Infeksi saluran kemih saat hamil harus diobati; bisa menyebar ke ginjal.',
  'Gebelikte ilaç ve takviye kullanımı': 'Obat dan suplemen saat hamil',
