  'Gebelikte ortaya çıkan ve doğumdan sonra çoğunlukla geçen kan şekeri yüksekliğidir.': 'Gula darah tinggi yang muncul saat hamil dan biasanya hilang setelah melahirkan.',
  'Gebelikte seyahat ve günlük yaşam': 'Bepergian dan keseharian saat hamil',
  'Gebelikte takip': 'Pemantauan kehamilan',
  'Gebelikte tehlike işaretleri': 'Tanda bahaya saat hamil',
  'Gebelikte yüksek riskli gıdalar için güncel sağlık önerilerini izleyin.': 'Saat hamil, ikuti anjuran kesehatan terbaru tentang makanan berisiko tinggi.',
  'Gebelikten önceki dönem sağlıklı bir gebelik için hazırlık zamanıdır.': 'Masa sebelum hamil adalah waktu mempersiapkan kehamilan yang sehat.',
