  'Gebeliğin yarısındasın. Bebek yutma hareketleri yapar; hareketleri belirginleşir.': 'Anda sudah di pertengahan. Bayi membuat gerakan menelan; gerakan makin jelas.',
  'Gece Lambası': 'Lampu Tidur',
  'Gece beslemelerini eşinle veya bir yakınınla paylaşmayı planla.': 'Rencanakan berbagi tugas menyusui malam dengan pasangan atau orang terdekat.',
  'Gece beslenmelerini paylaştırmak için sağılmış süt veya mama seçeneğini değerlendir.': 'Pertimbangkan ASI perah atau formula agar tugas menyusui malam bisa dibagi.',
  'Gece kuruluğu gündüzden aylar hatta yıllar sonra gelebilir.': 'Kering di malam hari bisa datang berbulan-bulan bahkan bertahun-tahun setelah kering di siang hari.',
  'Gece lambası': 'Lampu tidur',
  'Gece ve gündüz görevlerini birlikte paylaştırın; yazılı bir plan işe yarayabilir.': 'Bagi tugas siang dan malam bersama; rencana tertulis bisa membantu.',
  'Gece yarısını geçen uyku, ilgili günlere paylaştırılır. Ölçek 24 saattir.': 'Tidur yang melewati tengah malam dibagi ke hari-hari terkait. Skalanya 24 jam.',
  'Gece yolculuğu; isra': 'Perjalanan malam; Isra',
  'Gece-gündüz ayrımı ilk aylarda gelişir; uyku düzeni zamanla ve tutarlı rutinlerle oturur.': 'Ritme siang–malam berkembang di bulan-bulan pertama; dengan rutinitas yang konsisten, pola tidur akan teratur seiring waktu.',
