  'Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin.': 'Blender bila perlu; tambahkan daun segar dan air lemon setelah diangkat dari api, dan yoghurt setelah dihangatkan.',
