  'Gerginlik, uyku değişimi ve dikkat güçlüğünü gözlemleyin. Dinlenme, sosyal destek ve görev paylaşımı planlayın.': 'Perhatikan ketegangan, perubahan tidur, dan sulit berkonsentrasi. Rencanakan istirahat, dukungan sosial, dan pembagian tugas.',
