  'Gözlemeleri tavada iki tarafı da kızarana kadar pişirin.': 'Masak gözleme di wajan hingga kedua sisi kecokelatan.',
  'Gözler açılmaya başlar; seslere tepki verebilir.': 'Mata mulai terbuka; bayi bisa bereaksi terhadap suara.',
