  'Günlük işlerde küçük görevler ("ayakkabını getir"), boyama, parmak oyunları.': 'Tugas kecil dalam rutinitas ("ambil sepatumu"), mewarnai, permainan jari.',
  'Günlük işleri anlatarak konuş; çocuğun söylediklerini genişleterek tekrar et.': 'Ceritakan kegiatan sehari-hari; ulangi dan perluas ucapan anak.',
