  'Hazır olma belirtileri varsa ek gıdaya başla: tek tek, birkaç gün arayla, püre kıvamında. Demirden zengin besinler (et, yumurta sarısı, mercimek) öncelikli. Tuz, şeker ve bal eklenmez; anne sütü devam eder.': 'Jika ada tanda siap, mulai MPASI: satu per satu, berjeda beberapa hari, dalam bentuk bubur halus. Dahulukan makanan kaya zat besi (daging, kuning telur, lentil). Tanpa garam, gula, atau madu; menyusui tetap dilanjutkan.',
