  'Sert meyve parçaları bırakmayın; boğulma riskine dikkat edin.': 'Jangan sisakan potongan buah yang keras; waspadai risiko tersedak.',
  'Sert meyveleri (elma, armut, ayva) tavada 2 yemek kaşığı su ve tarçınla 5 dakika yumuşatıp soğutun.': 'Lunakkan buah keras (apel, pir, quince) di wajan dengan 2 sdm air dan kayu manis 5 menit lalu dinginkan.',
