  'Sesiniz': 'Suara Anda',
  'Sesler uygulama içinde matematiksel olarak üretilir. Brahms Ninnisi (1868) ve “Parla Parla Küçük Yıldız” ezgisi kamu malıdır; “Uyku melodisi” bu uygulama için bestelenmiştir.': 'Suara dibuat secara matematis di dalam aplikasi. Lagu Nina Bobo Brahms (1868) dan melodi "Twinkle, Twinkle, Little Star" (Bintang Kecil) adalah domain publik; "Melodi tidur" dibuat untuk aplikasi ini.',
