  'Seyahatten önce gebelik kartını ve tahlil sonuçlarını yanına al.': 'Bawa buku kehamilan dan hasil pemeriksaan saat bepergian.',
  'Sezaryen büyük bir karın ameliyatıdır; iyileşme genellikle 6–8 hafta sürer.': 'Operasi caesar adalah operasi perut besar; pemulihannya biasanya 6–8 minggu.',
  'Sezaryen sonrası ağır kaldırmaktan kaçın; öksürürken karnını yastıkla destekle.': 'Setelah caesar hindari mengangkat beban berat; tahan perut dengan bantal saat batuk.',
  'Sezaryen sonrası emzirme mümkündür; yan yatarak veya koltuk altı pozisyonu rahat olabilir.': 'Menyusui setelah caesar bisa dilakukan; posisi berbaring miring atau posisi football hold bisa nyaman.',
  'Sezaryen sonrası iyileşme': 'Pemulihan setelah operasi caesar',
  'Sezaryen sonrası tam iyileşme 6–8 hafta sürebilir.': 'Pemulihan penuh setelah caesar bisa memakan 6–8 minggu.',
  'Sezaryen tıbbi gerekliliklerde hayat kurtarıcıdır; büyük bir ameliyat olduğu için iyileşmesi daha uzundur.': 'Operasi caesar menyelamatkan nyawa bila diperlukan secara medis; sebagai operasi besar, pemulihannya lebih lama.',
  'Sezaryenden sonra da çoğu zaman mümkündür.': 'Sering kali juga bisa dilakukan setelah operasi caesar.',
  'Seçenek sun ("kırmızı mı mavi mi?") ve küçük görevler ver.': 'Beri pilihan ("merah atau biru?") dan tugas-tugas kecil.',
  'Seçenek sunma ("elma mı muz mu?"), kutu içine şekil yerleştirme, birlikte toplama oyunu.': 'Memberi pilihan ("apel atau pisang?"), mainan sortir bentuk, beres-beres bersama sebagai permainan.',
  'Seçenekleri ve hastanende uygulananları önceden öğren.': 'Cari tahu pilihan dan layanan di rumah sakit Anda sebelumnya.',
