  'Siyah-beyaz kontrastlı kartlar, yüzünü yavaşça sağa-sola hareket ettirerek takip ettirme, günde birkaç kez karın üstü oyun.': 'Kartu kontras hitam-putih, gerakkan wajah Anda perlahan ke kiri-kanan agar ia mengikuti, main tengkurap beberapa kali sehari.',
