  'Solukluk, halsizlik, iştahsızlık sürüyorsa.': 'Jika pucat, lemas, atau tidak nafsu makan berlanjut.',
  'Somon filetoları fırın kabına yerleştirin.': 'Letakkan fillet salmon di pinggan.',
  'Somon küplerini ekleyip 3–4 dakika, tüm yüzleri açık renge dönene kadar nazikçe çevirin.': 'Masukkan potongan salmon dan balik perlahan 3–4 menit hingga semua sisi berubah pucat.',
  'Somonları fırının orta rafında 15–18 dakika, eti çatalla kolayca ayrılana ve iç sıcaklığı 63 °C olana kadar pişirin.': 'Panggang salmon di rak tengah 15–18 menit hingga dagingnya mudah terlepas dengan garpu dan suhu dalam 63 °C.',
  'Somonları rezenelerin üzerine yerleştirin, sosun yarısını üzerlerine sürün ve portakal dilimlerini aralara dizin.': 'Letakkan salmon di atas adas, olesi setengah saus, dan selipkan irisan jeruk di sela-selanya.',
  'Somonları sebzelerin üzerine yerleştirin, kalan yağ, tuz ve limon suyunu sürün.': 'Letakkan salmon di atas sayuran dan olesi sisa minyak, garam, dan air lemon.',
  'Somonları sebzelerle tepsiye koyup limon sıkın.': 'Letakkan salmon di loyang bersama sayuran dan peras lemon di atasnya.',
  'Somonları sosla 10 dakika marine edin.': 'Marinasi salmon dalam saus 10 menit.',
  'Somonları soğuk suyla durulayıp kâğıt havluyla iyice kurulayın; derili tarafı alta gelecek şekilde tepsiye dizin.': 'Bilas salmon dengan air dingin, keringkan dengan tisu, tata dengan sisi kulit di bawah.',
  'Somonlu makarna': 'Pasta salmon',
  'Somonu fazla karıştırmayın; parçalar bütün kalırsa daha güzel görünür.': 'Jangan terlalu sering mengaduk salmon; potongan utuh tampak lebih menarik.',
  'Somonu pişirmeden 15 dakika önce buzdolabından çıkarırsanız daha eşit pişer.': 'Jika salmon dikeluarkan dari kulkas 15 menit sebelum dimasak, matangnya lebih merata.',
  'Somonu yapışmaz tavada derili tarafı altta 5 dakika pişirin.': 'Masak salmon dengan sisi kulit di bawah di wajan antilengket 5 menit.',
  'Somonu üzerine koyup yağ ve limon ekleyin.': 'Letakkan salmon di atasnya, tambahkan minyak dan lemon.',
  'Somonun içi tamamen pişene kadar yaklaşık 15-20 dakika fırınlayın.': 'Panggang sekitar 15-20 menit hingga bagian dalam salmon matang.',
