  'Son aylarda hareketlerin şekli değişir ama sayısı azalmamalıdır.': 'Di bulan-bulan terakhir jenis gerakan berubah, tetapi jumlahnya tidak boleh berkurang.',
  'Son açan gül': 'Mawar terakhir yang mekar',
  'Son bir saattir kasılmalar 5 dakikada bir geliyor ve en az 1 dakika sürüyor. Doktorunu ya da doğum yapacağın hastaneyi ara; sana söylenen plana göre yola çık.': 'Dalam satu jam terakhir, kontraksi datang setiap 5 menit dan berlangsung minimal 1 menit. Hubungi dokter atau rumah sakit tempat Anda akan melahirkan, dan berangkatlah sesuai rencana yang diberikan.',
  'Son büyüme ölçümü': 'Pengukuran pertumbuhan terakhir',
  'Son görüntülenenler': 'Baru dilihat',
  'Son iki haftada birçok gün kendini kötü hissetmişsin. Bu yalnız taşıman gereken bir yük değil; bir yakınınla ya da doktorunla konuş. Kendine zarar verme düşüncesi varsa hemen 112’yi ara.': 'Anda merasa tidak baik pada banyak hari dalam dua minggu terakhir. Anda tidak harus menanggungnya sendiri; bicarakan dengan orang terdekat atau dokter. Jika ada pikiran untuk menyakiti diri sendiri, segera hubungi nomor darurat setempat.',
