  'Tava kalabalık olursa balık kızarmaz, haşlanır; gerekirse iki partide pişirin.': 'Jika wajan terlalu penuh, ikan akan terkukus bukan tergoreng; masak dalam dua tahap bila perlu.',
  'Tavada 2 yemek kaşığı zeytinyağıyla patlıcanları orta ateşte 8 dakika, her yüzü hafif kızarana kadar soteleyin.': 'Tumis terung di wajan dengan 2 sdm minyak zaitun dengan api sedang 8 menit hingga tiap sisi sedikit kecokelatan.',
  'Tavada 2 yemek kaşığı zeytinyağıyla pırasa, havuç ve sarımsağı 5 dakika soteleyin; sıcak suyu ve yarım çay kaşığı tuzu ekleyip kapağı kapalı 8 dakika pişirin.': 'Tumis daun bawang perai, wortel, dan bawang putih dengan 2 sdm minyak zaitun 5 menit; tambahkan air panas dan ½ sdt garam lalu masak tertutup 8 menit.',
  'Tavada her yüzü 2 dakika kızartın.': 'Panggang di wajan 2 menit tiap sisi.',
  'Tavada her yüzü 3 dakika ısıtın.': 'Panaskan di wajan 3 menit tiap sisi.',
  'Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.': 'Goreng kedua sisi dengan api sedang; masak 12–18 menit sesuai ketebalan.',
  'Tavada pizza ekmeği': 'Roti pizza di wajan',
  'Tavada tereyağını eritin, sebzeyi ekleyip suyunu çekene kadar 4–5 dakika soteleyin.': 'Lelehkan mentega di wajan, masukkan sayuran, dan tumis 4–5 menit hingga airnya menguap.',
  'Tavada tereyağını eritip sucukları 2 dakika çevirin.': 'Lelehkan mentega di wajan dan tumis sucuk 2 menit.',
  'Tavada yağı kızdırın.': 'Panaskan minyak di wajan.',
  'Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.': 'Panaskan minyak di wajan dan tumis ayam dengan api besar hingga berwarna.',
  'Tavada zeytinyağıyla soğanı 3 dakika yumuşatın, salçayı ekleyip 1 dakika kavurun; rendelenmiş domatesi ve sıcak suyu ilave edip 3 dakika kaynatın.': 'Tumis bawang dengan minyak zaitun 3 menit, masukkan pasta tomat 1 menit; tambahkan tomat parut dan air panas, didihkan 3 menit.',
  'Tavada zeytinyağıyla tavukları yüksek ateşte 6 dakika soteleyin, tabağa alın.': 'Tumis ayam dengan minyak zaitun dengan api besar 6 menit lalu pindahkan ke piring.',
  'Tavada üzerine ağırlık koyarak her yüzü 2 dakika kızartın.': 'Panggang di wajan dengan pemberat di atasnya 2 menit tiap sisi.',
  'Tavayı iyice kızdırın; sebzeler kızarsın.': 'Panaskan wajan dengan baik agar sayuran kecokelatan.',
  'Tavuk 74°C iç sıcaklığa ulaşınca ocaktan alın.': 'Angkat saat suhu dalam ayam mencapai 74°C.',
  'Tavuk bagetleri ve patatesleri yağ, kekik ve biberle harmanlayıp tepsiye tek kat dizin.': 'Aduk paha ayam dan kentang dengan minyak, thyme, dan paprika lalu tata selapis di loyang.',
