  'Trafik, oyun alanı, su güvenliği ve yabancılarla sınırlar konusunda yaşa uygun konuşun. Bisiklet ve benzeri etkinliklerde uygun koruyucu ekipman kullanın.': 'Bicarakan sesuai usia tentang lalu lintas, taman bermain, keamanan di air, dan batasan dengan orang asing. Gunakan alat pelindung saat bersepeda dan kegiatan serupa.',
