  'Un, ceviz ve kabartma tozunu ekleyip yumuşak hamur elde edin.': 'Tambahkan tepung, kenari, dan baking powder hingga menjadi adonan lembut.',
  'Un, kabartma tozu ve ince kıyılmış cevizi ekleyip hamur yapın': 'Tambahkan tepung, baking powder, dan kenari cincang halus hingga menjadi adonan',
