  'Yaşınıza, sağlık geçmişinize ve risklerinize uygun taramaları aile hekiminizle planlayın. Randevularda sorularınızı ve kullandığınız ilaçları listeleyin.': 'Rencanakan skrining sesuai usia, riwayat kesehatan, dan risiko Anda bersama dokter keluarga. Buat daftar pertanyaan dan obat yang Anda minum untuk janji temu.',
