  'Yufkaları ikiye kesin, sosla ıslatın, harcı kenara koyup rulo yapın.': 'Potong lembar yufka jadi dua, basahi dengan saus, taruh isian di tepi, lalu gulung.',
  'Yufkaları kaynar suda 1 dakika haşlayıp soğuk suya alın.': 'Rebus lembar yufka 1 menit dalam air mendidih lalu pindahkan ke air dingin.',
  'Yufkaları parçalara ayırıp iç harçla küçük rulolar yapın.': 'Potong yufka menjadi bagian dan buat gulungan kecil dengan isian.',
  'Yufkaları soslayarak tepsiye kat kat serin, aralara peynir koyun.': 'Susun yufka berlapis di loyang, olesi saus, dan beri keju di antara lapisan.',
  'Yufkaları soslayıp iç harçla rulo yaparak tepsiye dizin.': 'Olesi yufka dengan saus, gulung dengan isian, dan tata di loyang.',
