  'İdrar yaparken yanma, sık idrara çıkma veya ateş.': 'Perih saat buang air kecil, sering pipis, atau demam.',
  'İdrar yolu enfeksiyonu': 'Infeksi saluran kemih',
  'İdrarın açık sarı renkte olması yeterli sıvı alımının basit bir göstergesidir.': 'Urine berwarna kuning muda adalah tanda sederhana Anda cukup minum.',
  'İffetli, namuslu': 'Suci, terhormat',
  'İhtiyacın olan aracı ara': 'Cari alat yang Anda butuhkan',
  'İhtiyaçlarınızı açık ve saygılı biçimde ifade etmeye çalışın. Yapamayacağınız işlere hemen söz vermek zorunda değilsiniz.': 'Cobalah menyampaikan kebutuhan Anda dengan jelas dan hormat. Anda tidak harus langsung berjanji melakukan hal yang tidak sanggup.',
  'İhtişam, gösteriş': 'Kemegahan, kemewahan',
  'İki adımlı küçük görevler ekleyin; başarıyı değil keşfi öne çıkarın.': 'Tambahkan tugas kecil dua langkah; utamakan eksplorasi, bukan keberhasilan.',
  'İki aşamalı basit yönergeleri, hayalî oyunu ve sosyal etkileşimi birlikte deneyimleyin.': 'Coba bersama perintah sederhana dua langkah, bermain pura-pura, dan interaksi sosial.',
  'İki blok üst üste koyma, büyük boya kalemiyle karalama (gözetimli), saklambaç benzeri basit oyunlar.': 'Menumpuk dua balok, mencoret dengan krayon tebal (diawasi), permainan petak umpet sederhana.',
  'İki dilli büyüyen çocuklarda kelime dağarcığı iki dile dağılabilir; bu gecikme anlamına gelmez.': 'Anak yang tumbuh dengan dua bahasa bisa membagi kosakatanya; ini bukan keterlambatan.',
  'İki elle tutulacak oyuncaklar, birbirine vurma (ritim), aynada yüz ifadeleri.': 'Mainan yang dipegang dengan dua tangan, memukul benda satu sama lain (irama), ekspresi wajah di cermin.',
  'İki forumun SQL dosyaları, RLS politikaları ve çok kullanıcılı testleri gerekli.': 'Berkas SQL, kebijakan RLS, dan uji multipengguna untuk kedua forum diperlukan.',
  'İki forumun canlı Supabase bağlantısı ve RLS politikaları doğrulandı': 'Koneksi Supabase langsung dan kebijakan RLS kedua forum telah diverifikasi',
  'İki haftadan uzun süren mutsuzluk, ilgi kaybı, umutsuzluk.': 'Sedih, kehilangan minat, atau putus asa lebih dari dua minggu.',
  'İki haftadan uzun süren mutsuzluk, umutsuzluk, uykusuzluk.': 'Sedih, putus asa, atau sulit tidur lebih dari dua minggu.',
  'İki sözcüklü cümleler yaygınlaşır; 50 civarı sözcük olağandır. Taklit ve hayali oyun artar.': 'Kalimat dua kata makin umum; sekitar 50 kata itu normal. Meniru dan bermain pura-pura bertambah.',
  'İki tarafını da içi tamamen pişene dek pişirin.': 'Masak kedua sisi hingga bagian dalam matang.',
  'İki tarafını da içi tamamen pişene kadar çevirerek pişirin.': 'Balik dan masak kedua sisi hingga bagian dalam matang.',
  'İki tarafını da içi tamamen pişene kadar çevirin.': 'Balik hingga kedua sisi dan bagian dalam matang.',
  'İki tarafını da yumurta tamamen pişene kadar pişirin.': 'Masak kedua sisi hingga telur matang sempurna.',
  'İki yaş: koşar, top atar, 2–3 sözcüklü cümleler kurar, basit iki aşamalı yönergeleri yapar. Tuvalet eğitimine hazırlık belirtileri görülebilir.': 'Dua tahun: berlari, melempar bola, membuat kalimat 2–3 kata, mengikuti perintah sederhana dua langkah. Tanda siap latihan toilet bisa muncul.',
  'İki yüzünü de içi pişene kadar orta ateşte kızartın.': 'Goreng kedua sisi dengan api sedang hingga matang di dalam.',
  'İki yüzünü de yumurta tamamen pişene kadar pişirin.': 'Masak kedua sisi hingga telur matang sempurna.',
  'İkinci kişi': 'Kontak kedua',
  'İkinci mayalanma yumuşaklığın anahtarıdır.': 'Pengembangan kedua adalah kunci kelembutan.',
  'İkinci trimester: düzenli kontrolleri ve doktorunun önerdiği taramaları takip et.': 'Trimester kedua: lanjutkan pemeriksaan rutin dan skrining yang direkomendasikan dokter.',
  'İkinci üç ay (14–27. hafta)': 'Trimester kedua (minggu 14–27)',
